```typescript
import { delay } from 'node:timers/promises';

/**
 * Executes a job with exponential backoff.
 * @param job The function to execute.
 * @param maxAttempts The maximum number of attempts.
 * @param initialDelay The initial delay in milliseconds.
 * @param factor The backoff factor (multiplier).
 * @returns A promise that resolves when the job is successful or all attempts are exhausted.
 */
async function executeWithBackoff<T>(
  job: () => Promise<T>,
  maxAttempts: number,
  initialDelay: number,
  factor: number
): Promise<T> {
  let attempts = 0;
  while (attempts < maxAttempts) {
    try {
      return await job();
    } catch (error) {
      console.error(`Attempt ${attempts + 1} failed: ${error}`);
      attempts++;
      if (attempts < maxAttempts) {
        const delayTime = initialDelay * Math.pow(factor, attempts - 1);
        console.log(`Waiting ${delayTime}ms before retrying...`);
        await delay(delayTime);
      } else {
        console.error(`All attempts exhausted. Failed job.`);
        throw error;
      }
    }
  }
}

