```typescript
// Import necessary packages
import { EventEmitter } from 'events';

// Define a class to manage cache invalidation
class CacheInvalidator {
  private cache: Map<string, Date>;
  private eventEmitter: EventEmitter;

  constructor() {
    this.cache = new Map();
    this.eventEmitter = new EventEmitter();
  }

  // Method to add data to the cache with a timestamp
  public addData(key: string, value: any): void {
    this.cache.set(key, new Date());
    this.emitCacheChange(key);
  }

  // Method to invalidate the cache for a specific key
  public invalidateCache(key: string): void {
    this.cache.delete(key);
    this.emitCacheChange(key);
  }

  // Method to emit a cache change event
  private emitCacheChange(key: string): void {
    this.eventEmitter.emit('cacheChange', key);
  }
}

