```typescript
// Import necessary modules
import express from 'express';
import { v4 as uuidv4 } from 'uuid';
import { User } from './user.model';

const app = express();
const port = 3000;

// Sample user model
interface User {
  id: string;
  email: string;
  password: string;
  magicLink: string | null;
}

// Sample users
const users: User[] = [
  { id: '1', email: 'user1@example.com', password: 'password123', magicLink: null },
  { id: '2', email: 'user2@example.com', password: 'password456', magicLink: null }
];

// Middleware to verify user authentication
const authenticateUser = (req: express.Request, res: express.Response, next: express.NextFunction) => {
  const { email, password } = req.body;
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ message: 'Invalid credentials' });
  }
  req.user = user;
  next();
};

// Route for generating magic link
app.post('/generate-magic-link', authenticateUser, (req: express.Request, res: express.Response) => {
  const { email } = req.body;
  const user = users.find(u => u.email === email);
  if (!user) {
    return res.status(401).json({ message: 'Invalid credentials' });
  }

  // Generate a unique magic link
  const magicLink = uuidv4();
  user.magicLink = magicLink;
  res.json({ message: 'Magic link generated', magicLink });
});

// Route for verifying magic link
app.post('/verify-magic-link', (req: express.Request, res: express.Response) => {
  const { magicLink } = req.body;
  const user = users.find(u => u.magicLink === magicLink);
  if (!user) {
    return res.status(401).json({ message: 'Invalid magic link' });
  }

  // Reset the magic link
  user.magicLink = null;
  res.json({ message: 'Magic link verified' });
});

// Start the server
app.listen(port, () => {
  console.log(`Server is running on http://localhost:${port}`);
});
```

### Explanation:

1. **User Model**: The `User` interface defines the structure of a user, including an ID, email, password, and a magic link.

2. **Authentication Middleware**: The `authenticateUser` middleware checks if the provided email and password match any user in the `users` array. If the credentials are correct, it sets the user in the request object.

3. **Generate Magic Link Route**: The `/generate-magic-link` route accepts a POST request with an email. It finds the user by email and generates a unique magic link using `uuidv4`. The magic link is then stored in the user's record.

4. **Verify Magic Link Route**: The `/verify-magic-link` route accepts a POST request with a magic link. It finds the user by magic link and resets the magic link to null, indicating that the magic link has been verified.

### Usage:

- **Generate Magic Link**: Send a POST request to `/generate-magic-link` with the user's email.
- **Verify Magic Link**: Send a POST request to `/verify-magic-link` with the magic link.

This example demonstrates basic user authentication with magic links using Express and TypeScript.

To solve real-time presence indicators in Kotlin, you can use the `WebSocket` API to establish a connection with a server that provides real-time updates. Here's a basic example of how you might set up a WebSocket client in Kotlin:

