import io.ktor.client.*
import io.ktor.client.engine.okhttp.OkHttpClient
import io.ktor.client.request.*
import io.ktor.http.*

fun main() {
    val client = HttpClient(OkHttpClient())
    val url = "https://example.com/presence"

    val request = Request.Builder()
        .url(url)
        .build()

    client.newCall(request).enqueue(object : Callback<HttpResponse> {
        override fun onResponse(call: Call, response: Response) {
            if (response.isSuccessful) {
                println("Presence updated: ${response.body().string()}")
            } else {
